import 'package:flutter/material.dart';
import 'package:carousel_slider/carousel_slider.dart';

class Thirdparty extends StatefulWidget {
  final String title;
  const Thirdparty({super.key, required this.title});

  @override
  State<Thirdparty> createState() => _ThirdpartyState();
}

class _ThirdpartyState extends State<Thirdparty> {
  final List<String> images = [
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
    'data:image/jpeg;base64,',
  ];

  @override
  Widget build(BuildContext context) {
    return Center(
      child: CarouselSlider(
        options: CarouselOptions(
          height: 400.0,
          autoPlay: true,
          enlargeCenterPage: true,
          enableInfiniteScroll: true,
          viewportFraction: 0.8,
        ),
        items: images.map((items) {
          return Container(
            width: double.infinity,
            margin: const EdgeInsets.all(5.0),
            decoration: BoxDecoration(
              borderRadius: BorderRadius.circular(10.0),
              image: DecorationImage(
                image: NetworkImage(items),
                fit: BoxFit.cover,
              ),
            ),
          );
        }).toList(),
      ),
    );
  }
}
